test_that("updateModelCode", {
  testData <- readRDS(file.path(testthat::test_path(), "test-04-modelSummary_dataExmpl.rds"))
  
  # test empty new code
  testRes <- updateModelCode(fruitsObj = testData$fruitsObj, newModelCode = "")
  expect_equal(testRes$modelCode, testData$fruitsObj$modelCode)
  
  # test update with new code
  testCode <- "{\n    for (h_ in 1:nTargets) {\n        for (k_ in 1:nProxies) {\n            for (j_ in 1:nFractions) {\n                component.contrib_[h_, j_, k_] <- W_[k_, j_] * \n                  sum(alpha_[h_, 1:nSources] * C_[1:nSources, \n                    j_] * (I_[1:nSources, j_, k_] + T_[k_]))/sum(alpha_[h_, \n                  1:nSources] * C_[1:nSources, j_])\n            }\n            mu[h_, k_] <- sum(component.contrib_[h_, 1:nFractions, \n                k_])/sum(W_[k_, 1:nFractions])\n            obsvn[h_, k_] ~ dnorm(mu[h_, k_], pow(obsvnError[h_, \n                k_], -2))\n        }\n    }\n    for (h_ in 1:nTargets) {\n        for (j_ in 1:nFractions) {\n            beta_[h_, j_] <- sum(alpha_[h_, 1:nSources] * C_[1:nSources, \n                j_])/sum(alpha_[h_, 1:nSources] %*% C_[1:nSources, \n                1:nFractions])\n        }\n    }\n    for (h_ in 1:nTargets) {\n        for (i_ in 1:nSources) {\n            for (j_ in 1:nFractions) {\n                aux6_[h_, i_, j_] <- alpha_[h_, i_] * C_[i_, \n                  j_]/sum(alpha_[h_, 1:nSources] * C_[1:nSources, \n                  j_])\n            }\n        }\n        for (k_ in 1:nProxies) {\n            for (i_ in 1:nSources) {\n                theta_[h_, k_, i_] <- sum(aux6_[h_, i_, 1:nFractions] * \n                  W_[k_, 1:nFractions])/sum(aux6_[h_, 1:nSources, \n                  1:nFractions] %*% W_[k_, 1:nFractions])\n            }\n        }\n    }\n    for (h_ in 1:nTargets) {\n        dirParams[h_, 1:nSources] <- q[hierMatch[h_], 1:nSources] * \n            sourceDirichPrior[1:nSources]\n        alpha_[h_, 1:nSources] ~ ddirch(dirParams[h_, 1:nSources])\n    }\n    for (i_ in 1:nSources) {\n        for (g_ in 1:nHierLevels) {\n            q[g_, i_] ~ dlnorm(muQ, sdQ)\n        }\n    }\n    muQ ~ dnorm(0, 5)\n    sdQ ~ dunif(0, 5)\n    for (k_ in 1:nProxies) {\n        for (j_ in 1:nFractions) {\n            for (i_ in 1:nSources) {\n                I_[i_, j_, k_] <- I0_[i_, j_, k_]\n            }\n        }\n    }\n    for (k_ in 1:nProxies) {\n        for (j_ in 1:nFractions) {\n            for (i_ in 1:nSources) {\n                I0_[i_, j_, k_] ~ dnorm(source[i_, j_, k_], pow(sourceUncert[i_, \n                  j_, k_], -2))\n            }\n        }\n    }\n    for (k_ in 1:nProxies) {\n        T_[k_] ~ dnorm(weightOffset[k_], pow(weightOffsetUncert[k_], \n            -2))\n    }\n    for (j_ in 1:nFractions) {\n        for (i_ in 1:nSources) {\n            C_[i_, j_] ~ T(dnorm(concentration[i_, j_], pow(concentrationUncert[i_, \n                j_], -2)), 0, 100)\n        }\n    }\n    for (k_ in 1:nProxies) {\n        for (j_ in 1:nFractions) {\n            W_[k_, j_] ~ T(dnorm(weights[k_, j_], pow(weightsUncert[k_, \n                j_], -2)), -1e-04, 100)\n        }\n    }\n}"
  testRes <- updateModelCode(fruitsObj = testData$fruitsObj, newModelCode = testCode)
  testExp <- "nimbleCode({\n  # likelihood\nfor (h_ in 1:nTargets){ # targets\n  for (k_ in 1:nProxies){  # proxies\n    for (j_ in 1:nFractions){  #  fractions\n      component.contrib_[h_, j_, k_] <- W_[k_,j_] * sum(alpha_[h_,1:nSources] *C_[1:nSources,j_] * \n                                                          (I_[1:nSources,j_,k_] + T_[k_])) /\n        sum(alpha_[h_,1:nSources] *C_[1:nSources,j_])\n    }\n    # Measurements on targets\n    mu[h_,k_] <- sum(component.contrib_[h_,1:nFractions,k_]) / sum(W_[k_, 1:nFractions]) \n    \n\n\nobsvn[h_,k_] ~ dnorm(mu[h_,k_], pow(obsvnError[h_,k_],-2))\n  }\n  \n\n\n\n}\n\n#contribution of components\nfor (h_ in 1:nTargets){ # targets\t\n  for (j_ in 1:nFractions){  #  fractions\n    beta_[h_, j_] <- sum(alpha_[h_,1:nSources]*C_[1:nSources,j_]) / sum(alpha_[h_,1:nSources]%*%C_[1:nSources,1:nFractions])\n  }\n}\n\n#contribution of a source towards a proxy signal\nfor (h_ in 1:nTargets){ # targets\t\n  for (i_ in 1:nSources){  #  sources\n    for (j_ in 1:nFractions){  #  fractions\n      aux6_[h_,i_,j_] <- alpha_[h_,i_]*C_[i_,j_]/sum(alpha_[h_,1:nSources]*C_[1:nSources,j_])\n    }\n  }\n  \n  for (k_ in 1:nProxies){ # proxies\n    for (i_ in 1:nSources){  #  sources\n      theta_[h_,k_, i_] <- sum(aux6_[h_,i_,1:nFractions]*W_[k_,1:nFractions]) / \n      sum(aux6_[h_,1:nSources,1:nFractions] %*% W_[k_,1:nFractions])\n    }\n  }\n}\n\n  # priors\n#prior for intake estimates\nfor (h_ in 1:nTargets){ # nTargets: number of individuals\n  dirParams[h_,1:nSources] <-  q[hierMatch[h_],1:nSources] * sourceDirichPrior[1:nSources]\n  alpha_[h_,1:nSources] ~ ddirch(dirParams[h_,1:nSources])\n}\n\nfor (i_ in 1:nSources){\n  for (g_ in 1:nHierLevels){ \n    q[g_, i_] ~ dlnorm(muQ,sdQ)\n  }\n}\nmuQ ~ dnorm(0,5)\nsdQ ~ dunif(0,5)\n  \n  # # prior for isotopic values of fractions in sources\nfor (k_ in 1:nProxies){  # proxies\n  for (j_ in 1:nFractions){  #  fractions\n    for (i_ in 1:nSources){  #  sources\n        I_[i_,j_,k_] <- I0_[i_,j_,k_]\n    }\n  }\n}\n  \n  # # prior for isotopic values of fractions in sources\nfor (k_ in 1:nProxies){  # proxies\n  for (j_ in 1:nFractions){  #  fractions\n    for (i_ in 1:nSources){  #  sources\n      I0_[i_,j_,k_] ~ dnorm(source[i_,j_,k_], pow(sourceUncert[i_,j_,k_],-2))\n    }\n  }\n}\n  \n  \n\n  # prior for offset\nfor (k_ in 1:nProxies){  # proxies measured per target\n  T_[k_] ~ dnorm(weightOffset[k_], pow(weightOffsetUncert[k_],-2))\n}\n  \n  # prior for concentration values of fractions in sources\nfor (j_ in 1:nFractions){  # components of food group\n  for (i_ in 1:nSources){  # food groups\n  C_[i_,j_] ~ T(dnorm(concentration[i_,j_],\n        pow(concentrationUncert[i_,j_],-2)),0,100)\n  }\n}\n\n  # prior for  weight contribution\nfor (k_ in 1:nProxies){  # proxies measured per target\n  for (j_ in 1:nFractions){  # fractions\n    W_[k_, j_] ~ T(dnorm(weights[k_,j_],\n                               pow(weightsUncert[k_,j_],-2)),-0.0001,100)\n  }\n}\n\n  \n  \n  \n})"
  expect_equal(testRes$modelCode, tmplEval(tmpl(testExp)))
})
